@ExtendWith(MockitoExtension.class)  // required to process annotations
class OrderServiceTest {

    @Mock
    private OrderRepository mockRepository;

    @Mock
    private EmailService mockEmailService;

    @Spy
    private PriceCalculator spyCalculator = new PriceCalculator();

    @InjectMocks
    private OrderService service;  // Mockito creates this and injects mocks

    @Test
    void testPlaceOrder() {
        var order = new Order(1L, "Laptop", 999.99);
        when(mockRepository.save(any(Order.class))).thenReturn(order);

        var result = service.placeOrder(order);

        // service was automatically instantiated with all dependencies
        assertEquals(1L, result.id());
        verify(mockEmailService).sendConfirmation("Laptop");  // injected mock tracked interaction
        verify(mockRepository).save(order);
    }
}

// The class under test needs a constructor
class OrderService {
    private final OrderRepository repository;
    private final EmailService emailService;
    private final PriceCalculator calculator;

    // Mockito calls this constructor with the three injected mocks
    public OrderService(OrderRepository repository, EmailService emailService, PriceCalculator calculator) {
        this.repository = repository;
        this.emailService = emailService;
        this.calculator = calculator;
    }
}
