@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {

    @Spy
    private PaymentService spyService = new PaymentService();

    @Test
    void dangerousStubbing() {
        // WRONG: when() calls the real checkFraud method during setup
        // If checkFraud throws exception or has side effects, test fails here
        when(spyService.checkFraud("card123")).thenReturn(false);

        var result = spyService.processPayment("card123", 100.0);
        assertTrue(result);  // stub applied, but real method ran once during setup
    }

    @Test
    void safeStubbing() {
        // CORRECT: doReturn never invokes the real checkFraud method
        doReturn(false).when(spyService).checkFraud("card123");

        var result = spyService.processPayment("card123", 100.0);
        assertTrue(result);  // stub applied cleanly, no unwanted execution
    }

    @Test
    void withMockBothWork() {
        var mockRepo = mock(OrderRepository.class);
        // Both syntaxes identical for mocks—no real method exists
        when(mockRepo.findById(1L)).thenReturn(Optional.of(new Order(1L, "Book")));
        doReturn(Optional.of(new Order(2L, "Pen"))).when(mockRepo).findById(2L);

        assertEquals("Book", mockRepo.findById(1L).get().item());
        assertEquals("Pen", mockRepo.findById(2L).get().item());
    }
}

class PaymentService {
    boolean processPayment(String cardNumber, double amount) {
        return !checkFraud(cardNumber);  // calls method we want to stub
    }

    boolean checkFraud(String cardNumber) {
        throw new RuntimeException("Real fraud check—slow and flaky!");
    }
}
