class PaymentServiceTest {
    @Mock
    private PaymentGateway mockGateway; // All methods return null/defaults

    @Spy
    private PaymentValidator spyValidator = new PaymentValidator(); // Real object

    @Test
    void testMockBehavior() {
        when(mockGateway.charge(100)).thenReturn("SUCCESS");
        var result = mockGateway.charge(100); // Returns "SUCCESS"
        var other = mockGateway.refund(50); // Returns null (no stub)
    }

    @Test
    void testSpyBehavior() {
        // Real validateAmount() runs unless we stub it
        var realResult = spyValidator.validateAmount(100); // Runs actual code

        doReturn(false).when(spyValidator).validateAmount(0); // Override one method
        var stubbedResult = spyValidator.validateAmount(0); // Returns false

        verify(spyValidator, times(2)).validateAmount(anyInt());
    }
}
