// Fake: real implementation using HashMap
class FakeUserRepository implements UserRepository {
    private final Map<Long, User> storage = new HashMap<>();
    private Long nextId = 1L;

    public User save(User user) {
        if (user.id() == null) {
            user = new User(nextId++, user.name(), user.email());
        }
        storage.put(user.id(), user); // Real storage logic
        return user;
    }

    public Optional<User> findById(Long id) {
        return Optional.ofNullable(storage.get(id)); // Real lookup
    }
}

// Mock: Mockito-generated hollow shell
@Test
void testWithMock() {
    var mockRepo = mock(UserRepository.class);
    var user = new User(1L, "Alice", "alice@example.com");
    when(mockRepo.save(any())).thenReturn(user); // Programmed response

    var result = mockRepo.save(user);
    verify(mockRepo).save(user); // Only verifies interaction, no real storage
}
